{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret udelader det centrale minimumskrav om journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik (§ 37, stk. 3), og gengiver ikke 'som udgangspunkt' for epikrisen. Det gør epikrise/journalnotater til 'vedlæg så vidt muligt' og tilføjer en række krav, som kilderne ikke indeholder: en aktuel lægelig vurdering med prognose og beskrivelse af, hvorfor tilstanden gør studiejob vanskeligt. Det nævner heller ikke, at dokumentationen skal beskrive den varige funktionsnedsættelse (kun 'om den forventes at være varig')."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de tre kritiske elementer er epikrisen/afslutningsbrevet med. Journalmateriale fra de angivne kildetyper fremgår ikke som minimumskrav, kun 'journalnotater' fra forløbet. Kravet om, at materialet skal beskrive den varige funktionsnedsættelse, er kun delvist dækket. Elementerne er derfor ikke alle kommunikeret."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation en ansøgning skal indeholde efter afsluttet behandling."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer krav uden støtte i materialet: en aktuel lægelig vurdering med prognose og behandlingsresultat, en beskrivelse af hvorfor følgerne gør et studiejob vanskeligt, og at en kort erklæring fra egen læge kan være utilstrækkelig. Kilderne kræver journaler, en beskrivelse af den varige funktionsnedsættelse og aktualitet (§ 37, stk. 4) samt som udgangspunkt epikrise eller afslutningsbrev."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke 'som udgangspunkt' for epikrisen eller afslutningsbrevet. Det nævner ikke, at titlen ikke i sig selv afgør tilstrækkeligheden, selvom det antyder, at indholdet har betydning. Forbeholdet er kun delvist og uden for den kildebundne ramme."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: dokumentationen skal vise tilstand, forløb og nuværende påvirkning, og konklusionerne følger af dette. Der er ingen indbyrdes modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gengiver ikke kildens modalitet. Det bruger 'bør' og 'så vidt muligt' om elementer, som vejledningen formulerer som minimumskrav ('skal som minimum indeholde journaler'). Det gør et udgangspunkt for epikrise til noget, der kun bør vedlægges. Dermed bliver et krav til en blød anbefaling, og sproget om tilstrækkelighed ('normalt ikke nok', 'kan være utilstrækkelig') har ingen kildestøtte."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "partial",
      "reason": "Svaret nævner epikrise eller afsluttende journalnotat efter afsluttet behandling, men som 'vedlæg så vidt muligt', uden at gengive 'som udgangspunkt' fra vejledningen."
    },
    "A32": {
      "label": "partial",
      "reason": "Epikrise eller afsluttende journalnotat er nævnt som første dokumenttype, men uden den præcise kobling til udgangspunktet i vejledningen, og med blød modalitet."
    }
  },
  "overall_notes": "Svaret er relevant og sammenhængende, men uden kildeangivelse. Det mangler minimumskravet om journaler fra de angivne behandlertyper og kravet om beskrivelse af den varige funktionsnedsættelse, og det tilføjer ukildebaserede krav (aktuel vurdering, prognose, effekt på studiejob). Det gengiver heller ikke 'som udgangspunkt' præcist."
}

